<?php
require_once __DIR__ . '/../../admin/implements/conexion.php';exigirAdmin();$q=trim($_GET['buscar']??'');$estado=$_GET['estado']??'';$sql="SELECT p.*,u.nombre usuario,l.titulo libro,IF(p.estado_prestamo='Activo' AND p.fecha_devolucion<CURDATE(),'Atrasado',p.estado_prestamo) estado_vista FROM prestamos p JOIN usuarios u ON u.id_usuario=p.id_usuario JOIN libros l ON l.id_libro=p.id_libro WHERE 1=1";$args=[];if($q!==''){$sql.=' AND (u.nombre LIKE ? OR l.titulo LIKE ?)';$args[]='%'.$q.'%';$args[]='%'.$q.'%';}if(!empty($_GET['fecha'])&&fechaValida($_GET['fecha'])){$sql.=' AND (p.fecha_prestamo=? OR p.fecha_devolucion=?)';$args[]=$_GET['fecha'];$args[]=$_GET['fecha'];}if($estado==='Devuelto')$sql.=" AND p.estado_prestamo='Devuelto'";elseif($estado==='Activo')$sql.=" AND p.estado_prestamo='Activo' AND p.fecha_devolucion>=CURDATE()";elseif($estado==='Atrasado')$sql.=" AND p.estado_prestamo='Activo' AND p.fecha_devolucion<CURDATE()";$sql.=' ORDER BY p.id_prestamo DESC';$s=$pdo->prepare($sql);$s->execute($args);$rows=$s->fetchAll();iniciarPagina('Historial');barraNavegacion('historial.php');
?>
<div class="encabezado-pagina"><div><span class="sobrelinea">REGISTROS</span><h1>Historial de préstamos</h1><p>Consulta todos los préstamos realizados.</p></div></div><section class="panel"><form class="row g-2 mb-3"><div class="col-md-5"><input class="form-control" name="buscar" placeholder="Buscar usuario o libro" value="<?= escapar($q); ?>"></div><div class="col-md-3"><input class="form-control" type="date" name="fecha" value="<?= escapar($_GET['fecha']??''); ?>"></div><div class="col-md-2"><select class="form-select" name="estado"><option value="">Todos</option><?php foreach(['Activo','Devuelto','Atrasado'] as $x): ?><option value="<?= escapar($x); ?>" <?= $estado===$x?'selected':''; ?>><?= escapar($x); ?></option><?php endforeach; ?></select></div><div class="col-md-2"><button class="btn btn-outline-primary">Filtrar</button></div></form><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Usuario</th><th>Libro</th><th>Préstamo</th><th>Devolución</th><th>Estado</th></tr></thead><tbody><?php foreach($rows as $p): ?><tr><td><?= escapar($p['usuario']); ?></td><td><?= escapar($p['libro']); ?></td><td><?= escapar($p['fecha_prestamo']); ?></td><td><?= escapar($p['fecha_devolucion']); ?></td><td><?= escapar($p['estado_vista']); ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5" class="text-center">No se encontraron préstamos.</td></tr><?php endif; ?></tbody></table></div></section><?php finPagina(); ?>
